    [34896] = {
        source = "Trader Narasu (Kurenai) / Provisioner Nasela (The Mag'har) - Outland Nagrand",
        category = "Reputation",
        faction = "all",
        requirements = "Kurenai Exalted on Alliance or The Mag'har Exalted on Horde; Apprentice Riding.",
        cost = "80 gold at Exalted before any additional discounts.",
        tips = "Riding and War talbuks are separate unarmored and armored collection entries. They scale with riding skill; the War version does not buy a speed upgrade. Save any Oshu'gun Crystal Powder Samples found during the grind if you also want the two Halaa talbuks.",
        sourceUrls = { "https://www.wowhead.com/item=29227", "https://www.wowhead.com/item=29102" },
        waypoints = {
            { mapID = 107, x = 0.46, y = 0.23, step = 2, label = "Laughing Skull Ruins - ogres and Obsidian Warbeads" },
            { mapID = 107, x = 0.29, y = 0.26, step = 3, label = "Warmaul Hill - alternative ogre farming area" },
            {
                mapID = 107,
                x = 0.5479999999999999,
                y = 0.708,
                step = 4,
                label = "Alliance: Warden Moi'bff Jill - 10-bead turn-ins",
            },
            {
                mapID = 107,
                x = 0.5579999999999999,
                y = 0.37799999999999995,
                step = 4,
                label = "Horde: Warden Bullrok - 10-bead turn-ins",
            },
            {
                mapID = 107,
                x = 0.545,
                y = 0.7509999999999999,
                step = 6,
                label = "Alliance: Trader Narasu - Exalted mount vendor",
            },
            { mapID = 107, x = 0.535, y = 0.369, step = 6, label = "Horde: Provisioner Nasela - Exalted mount vendor" },
        },
        itemId = 29102,
        name = "Cobalt War Talbuk",
        stepCount = 7,
        acquisition = "Difficulty: Medium - Farm ogres and repeatable warbead turn-ins to Exalted, then buy the chosen color.\n\n1. Go to Nagrand in OUTLAND. Alliance earns Kurenai reputation and buys from Trader Narasu in Telaar; Horde earns The Mag'har reputation and buys from Provisioner Nasela in Garadar. These are the original Outland reputations, not the Mag'har allied race or Draenor's Nagrand factions.\n\n2. Start killing Warmaul ogres in Laughing Skull Ruins around 46.0, 23.0. Loot every corpse for Obsidian Warbeads (25433). The kills themselves award your faction reputation, including while working toward Neutral; you do not have to wait for daily quests.\n\n3. If Laughing Skull is crowded, move to the ogres at Warmaul Hill around 29.0, 26.0 and its caves. Keep all Obsidian Warbeads. Outland faction quests are optional extra reputation, but the repeatable ogre-and-bead route can finish the grind.\n\n4. Once your faction will speak to you, take a stack of 10 Obsidian Warbeads to Warden Moi'bff Jill at 54.8, 70.8 in Telaar (Alliance) or Warden Bullrok at 55.8, 37.8 in Garadar (Horde). Complete Fierce Enemies, then the repeatable More Warbeads! turn-in.\n\n5. Repeat the ogre kills and 10-bead hand-ins until Kurenai or The Mag'har is Exalted. A normal hand-in awards 500 reputation before bonuses, and it is repeatable without a daily limit. Hand the beads to your faction warden, not The Consortium, if your goal is these mounts.\n\n6. At Exalted, visit Trader Narasu at 54.5, 75.1 in Telaar (Alliance) or Provisioner Nasela at 53.5, 36.9 in Garadar (Horde). Buy Reins of the Cobalt War Talbuk. Its normal Exalted price is 80 gold; the faction item IDs are 29227 (Alliance) and 29102 (Horde).\n\n7. Use the reins from your bags. You may buy every other missing talbuk color from the same vendor after this one reputation grind; the first purchase does not consume or reset your reputation.",
        wowheadUrl = "https://www.wowhead.com/item=29102",
        difficultyReason = "Farm ogres and repeatable warbead turn-ins to Exalted, then buy the chosen color.",
        difficulty = "medium",
    },
